using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Http;
using VisualRelay.App.Services;
using VisualRelay.App.ViewModels;
using VisualRelay.App.Views;

namespace VisualRelay.Tests;

/// <summary>
/// In-memory handler tests for the transport-agnostic control API pipeline.
/// The handler (<see cref="ControlServer.BuildHandler"/>) operates on
/// <see cref="HttpContext"/> and is exercised directly via
/// <see cref="DefaultHttpContext"/> — no sockets, no ports, no TestServer.
///
/// These tests define the target behaviour the Kestrel port must deliver.
/// They currently FAIL because BuildHandler is a stub that returns 500 for
/// everything; they will pass once the routing logic is ported.
/// </summary>
public sealed class ControlServerKestrelHandlerTests
{
    /// <summary>
    /// Creates a handler delegate and invokes it with a bare
    /// DefaultHttpContext whose response body is a MemoryStream so the
    /// test can read the response afterwards.
    /// </summary>
    private static async Task<(HttpContext Context, ControlApi Api, MainWindowViewModel Vm)> InvokeAsync(
        string method, string path, string? token = null, string? requestBody = null,
        Dictionary<string, string>? requestHeaders = null)
    {
        var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
        var window = new MainWindow { DataContext = vm };
        var api = new ControlApi(vm, window);
        var options = new ControlServerOptions(Enabled: true, Port: 0, Token: token);
        var handler = ControlServer.BuildHandler(api, options);

        var context = new DefaultHttpContext();
        context.Request.Method = method;
        context.Request.Path = path;
        context.Response.Body = new MemoryStream();

        if (requestHeaders is not null)
        {
            foreach (var (key, value) in requestHeaders)
            {
                context.Request.Headers[key] = value;
            }
        }

        if (requestBody is not null)
        {
            var bytes = Encoding.UTF8.GetBytes(requestBody);
            context.Request.Body = new MemoryStream(bytes);
            context.Request.Headers.ContentLength = bytes.Length;
        }

        await handler(context);
        context.Response.Body.Position = 0;
        return (context, api, vm);
    }

    private static async Task<string> ReadBodyAsync(HttpContext context)
    {
        using var reader = new StreamReader(context.Response.Body, Encoding.UTF8, leaveOpen: true);
        return await reader.ReadToEndAsync();
    }

    private static async Task<JsonDocument> ReadJsonBodyAsync(HttpContext context)
    {
        var body = await ReadBodyAsync(context);
        return JsonDocument.Parse(body);
    }

    // ── Health ──────────────────────────────────────────────────────────

    [Fact]
    public async Task HealthEndpoint_Returns200_WithJsonBody()
    {
        var (context, _, _) = await InvokeAsync("GET", "/health");

        Assert.Equal(200, context.Response.StatusCode);
        Assert.Equal("application/json", context.Response.ContentType);

        using var doc = await ReadJsonBodyAsync(context);
        Assert.Equal("ok", doc.RootElement.GetProperty("status").GetString());
        Assert.Equal("Visual Relay", doc.RootElement.GetProperty("app").GetString());
    }

    // ── Token auth ──────────────────────────────────────────────────────

    [Fact]
    public async Task Token_WhenConfigured_Returns401_WithoutHeader()
    {
        var (context, _, _) = await InvokeAsync("GET", "/health", token: "letmein");

        Assert.Equal(401, context.Response.StatusCode);
        Assert.Equal("application/json", context.Response.ContentType);

        using var doc = await ReadJsonBodyAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("unauthorized", doc.RootElement.GetProperty("error").GetString());
    }

    [Fact]
    public async Task Token_WhenConfigured_Returns200_WithCorrectHeader()
    {
        var (context, _, _) = await InvokeAsync(
            "GET", "/health", token: "letmein",
            requestHeaders: new Dictionary<string, string> { ["X-VR-Token"] = "letmein" });

        Assert.Equal(200, context.Response.StatusCode);

        using var doc = await ReadJsonBodyAsync(context);
        Assert.Equal("ok", doc.RootElement.GetProperty("status").GetString());
    }

    [Fact]
    public async Task Token_GatesAllRoutes_IncludingHealth()
    {
        // /health is also gated — an unauthorized caller learns nothing.
        var (context, _, _) = await InvokeAsync("GET", "/health", token: "s3cret");

        Assert.Equal(401, context.Response.StatusCode);
    }

    [Fact]
    public async Task Token_WithoutToken_AllRoutesSucceed()
    {
        // No token configured → no auth; every route passes through.
        var (context, _, _) = await InvokeAsync("GET", "/health", token: null);

        Assert.Equal(200, context.Response.StatusCode);
    }

    // ── 404 ─────────────────────────────────────────────────────────────

    [Fact]
    public async Task UnknownRoute_Returns404_Json()
    {
        var (context, _, _) = await InvokeAsync("GET", "/nonexistent");

        Assert.Equal(404, context.Response.StatusCode);
        Assert.Equal("application/json", context.Response.ContentType);

        using var doc = await ReadJsonBodyAsync(context);
        Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
        Assert.Equal("not found", doc.RootElement.GetProperty("error").GetString());
    }

    [Fact]
    public async Task WrongMethodOnRoute_Returns404()
    {
        // POST /health is not a valid route (only GET).
        var (context, _, _) = await InvokeAsync("POST", "/health");

        Assert.Equal(404, context.Response.StatusCode);
    }

    // ── Index page ──────────────────────────────────────────────────────

    [Fact]
    public async Task IndexPage_Returns200_WithHtmlContentType()
    {
        var (context, _, _) = await InvokeAsync("GET", "/");

        Assert.Equal(200, context.Response.StatusCode);
        Assert.Equal("text/html; charset=utf-8", context.Response.ContentType);

        var body = await ReadBodyAsync(context);
        Assert.StartsWith("<!DOCTYPE html>", body, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("<title>Visual Relay — Control API</title>", body, StringComparison.Ordinal);
    }

    [Fact]
    public async Task IndexPage_NonGet_Returns404()
    {
        var (context, _, _) = await InvokeAsync("POST", "/");

        Assert.Equal(404, context.Response.StatusCode);
    }

    // ── Screenshot ──────────────────────────────────────────────────────
    // Screenshot tests need the Avalonia headless UI thread because
    // ControlApi.CaptureScreenshotAsync calls Dispatcher.UIThread.

    [Collection("Headless")]
    public sealed class ScreenshotAndStateTests
    {
        private static async Task<(HttpContext Context, ControlApi Api, MainWindowViewModel Vm)> InvokeOnUiAsync(
            string method, string path, string? token = null)
        {
            var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
            var window = new MainWindow { DataContext = vm };
            var api = new ControlApi(vm, window);
            var options = new ControlServerOptions(Enabled: true, Port: 0, Token: token);
            var handler = ControlServer.BuildHandler(api, options);

            var context = new DefaultHttpContext();
            context.Request.Method = method;
            context.Request.Path = path;
            context.Response.Body = new MemoryStream();

            await handler(context);
            context.Response.Body.Position = 0;
            return (context, api, vm);
        }

        [AvaloniaFact]
        public async Task Screenshot_ReturnsPngContentType()
        {
            var (context, _, _) = await InvokeOnUiAsync("GET", "/screenshot");

            Assert.Equal(200, context.Response.StatusCode);
            Assert.Equal("image/png", context.Response.ContentType);
        }

        [AvaloniaFact]
        public async Task Screenshot_WithPath_ReturnsXScreenshotPathHeader()
        {
            var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
            var window = new MainWindow { DataContext = vm };
            var api = new ControlApi(vm, window);
            var options = new ControlServerOptions(Enabled: true, Port: 0, Token: null);
            var handler = ControlServer.BuildHandler(api, options);

            var targetPath = Path.Combine(Path.GetTempPath(), "vr-kestrel-test-shot.png");
            try
            {
                var context = new DefaultHttpContext();
                context.Request.Method = "GET";
                context.Request.Path = "/screenshot";
                context.Request.QueryString = new QueryString($"?path={Uri.EscapeDataString(targetPath)}");
                context.Response.Body = new MemoryStream();

                await handler(context);
                context.Response.Body.Position = 0;

                Assert.Equal(200, context.Response.StatusCode);
                Assert.Equal("image/png", context.Response.ContentType);

                // X-Screenshot-Path header is set when a path was given and written.
                Assert.True(context.Response.Headers.TryGetValue("X-Screenshot-Path", out var headerValues));
                var resolvedPath = headerValues.FirstOrDefault();
                Assert.NotNull(resolvedPath);
                Assert.Equal(Path.GetFullPath(targetPath), resolvedPath);
            }
            finally
            {
                if (File.Exists(targetPath))
                {
                    File.Delete(targetPath);
                }
            }
        }

        [AvaloniaFact]
        public async Task State_Returns200_WithJsonBody()
        {
            var (context, _, _) = await InvokeOnUiAsync("GET", "/state");

            Assert.Equal(200, context.Response.StatusCode);
            Assert.Equal("application/json", context.Response.ContentType);

            using var reader = new StreamReader(context.Response.Body, Encoding.UTF8, leaveOpen: true);
            var body = await reader.ReadToEndAsync();
            using var doc = JsonDocument.Parse(body);
            Assert.True(doc.RootElement.TryGetProperty("commands", out _));
        }
    }

    // ── Commands ────────────────────────────────────────────────────────
    // Command tests need the Avalonia headless UI thread because
    // ControlApi.InvokeCommandAsync calls Dispatcher.UIThread.

    [Collection("Headless")]
    public sealed class CommandTests
    {
        private static async Task<(HttpContext Context, MainWindowViewModel Vm)> InvokeCommandAsync(
            string commandName, string? body = null, string? token = null,
            Dictionary<string, string>? extraHeaders = null)
        {
            var vm = new MainWindowViewModel(new DictionaryEnvironmentAccessor { ["XDG_CONFIG_HOME"] = Path.GetTempPath() });
            var window = new MainWindow { DataContext = vm };
            var api = new ControlApi(vm, window);
            var options = new ControlServerOptions(Enabled: true, Port: 0, Token: token);
            var handler = ControlServer.BuildHandler(api, options);

            var context = new DefaultHttpContext();
            context.Request.Method = "POST";
            context.Request.Path = $"/command/{commandName}";
            context.Response.Body = new MemoryStream();

            if (token is not null)
            {
                // No auth header → the handler may reject with 401.
                // Callers that want auth must add it via extraHeaders.
            }

            if (extraHeaders is not null)
            {
                foreach (var (key, value) in extraHeaders)
                {
                    context.Request.Headers[key] = value;
                }
            }

            if (body is not null)
            {
                var bytes = Encoding.UTF8.GetBytes(body);
                context.Request.Body = new MemoryStream(bytes);
                context.Request.Headers.ContentLength = bytes.Length;
            }

            await handler(context);
            context.Response.Body.Position = 0;
            return (context, vm);
        }

        private static async Task<JsonDocument> ReadJsonAsync(HttpContext context)
        {
            using var reader = new StreamReader(context.Response.Body, Encoding.UTF8, leaveOpen: true);
            var body = await reader.ReadToEndAsync();
            return JsonDocument.Parse(body);
        }

        // ── Bodyless POST (the key behavioural change) ──────────────────

        /// <summary>
        /// Under Kestrel (RFC 9112), a POST with no Content-Length is a
        /// valid empty-body request — the command MUST execute and return 200.
        /// This is the deliberate semantic change from the old HttpListener
        /// 411 guard.
        /// </summary>
        [AvaloniaFact]
        public async Task BodylessPost_NoContentLength_Returns200_AndExecutesCommand()
        {
            var (context, vm) = await InvokeCommandAsync("pause-toggle");

            Assert.Equal(200, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("pause-toggle", doc.RootElement.GetProperty("command").GetString());

            // Command executed: PauseRequested flipped.
            Assert.True(vm.PauseRequested,
                "A bodyless POST must execute the command. PauseRequested should be true.");
        }

        /// <summary>
        /// A POST with Content-Length: 0 is semantically identical to a
        /// bodyless POST under Kestrel — both are valid empty-body requests.
        /// </summary>
        [AvaloniaFact]
        public async Task ContentLengthZero_Post_Returns200_AndExecutesCommand()
        {
            var (context, vm) = await InvokeCommandAsync(
                "pause-toggle",
                extraHeaders: new Dictionary<string, string> { ["Content-Length"] = "0" });

            Assert.Equal(200, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.True(doc.RootElement.GetProperty("ok").GetBoolean());

            Assert.True(vm.PauseRequested,
                "A Content-Length: 0 POST must execute the command. PauseRequested should be true.");
        }

        // ── Disabled command ────────────────────────────────────────────

        [AvaloniaFact]
        public async Task DisabledCommand_Returns409()
        {
            // run-selected is disabled when no task is selected.
            var (context, _) = await InvokeCommandAsync("run-selected");

            Assert.Equal(409, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("disabled", doc.RootElement.GetProperty("error").GetString());
        }

        // ── Unknown command ─────────────────────────────────────────────

        [AvaloniaFact]
        public async Task UnknownCommand_Returns404()
        {
            var (context, _) = await InvokeCommandAsync("nonexistent-command");

            Assert.Equal(404, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("unknown command", doc.RootElement.GetProperty("error").GetString());
        }

        // ── Confirm-gated command ───────────────────────────────────────

        [AvaloniaFact]
        public async Task ConfirmGatedCommand_WithoutConfirm_Returns409_AndNoEffect()
        {
            // mark-done requires {"confirm":true} — an empty-body POST
            // does not carry confirm, so the command must be refused.
            var (context, vm) = await InvokeCommandAsync("mark-done");

            Assert.Equal(409, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("confirmation required", doc.RootElement.GetProperty("error").GetString());

            // No task was selected, but more importantly the command was
            // gated BEFORE execution — confirm-gated safety holds.
        }

        // ── Token auth on commands ──────────────────────────────────────

        [AvaloniaFact]
        public async Task Command_WithToken_Returns401_WithoutHeader()
        {
            var (context, _) = await InvokeCommandAsync("pause-toggle", token: "s3cret");

            Assert.Equal(401, context.Response.StatusCode);

            using var doc = await ReadJsonAsync(context);
            Assert.False(doc.RootElement.GetProperty("ok").GetBoolean());
            Assert.Equal("unauthorized", doc.RootElement.GetProperty("error").GetString());
        }

        [AvaloniaFact]
        public async Task Command_WithToken_Returns200_WithCorrectHeader()
        {
            var (context, vm) = await InvokeCommandAsync(
                "pause-toggle", token: "letmein",
                extraHeaders: new Dictionary<string, string> { ["X-VR-Token"] = "letmein" });

            Assert.Equal(200, context.Response.StatusCode);
            Assert.True(vm.PauseRequested);
        }
    }
}
